R=/scratch/jjyeung/orch_n30
date -u +%TZ; free -g | sed -n 2p
for w in sb_mdrev sb_mask_phrase; do mkdir -p $R/$w/in $R/$w/out; echo  | base64 -d | tar xzf - -C $R/$w/in; (cd $R/$w/in && sha256sum -c --quiet SHA256SUMS && echo "$w in OK"); done
mkdir -p $R/sb_mdrev/prompts; echo  | base64 -d > $R/sb_mdrev/prompts/sb_mdrev.md
mkdir -p $R/sb_rkfam/prompts $R/sb_rkfam/out; echo  | base64 -d > $R/sb_rkfam/prompts/sb_rkfam.md
{ echo sb_mdrev; cat $R/sb_queue/queue.txt; echo sb_rkfam; } > $R/sb_queue/q.tmp; cat $R/sb_queue/q.tmp > $R/sb_queue/queue.txt; echo Q: $(cat $R/sb_queue/queue.txt | tr "\n" " ")
cp $R/sb_cursor_probe/AGENTS.md $R/sb_mask_phrase/AGENTS.md; echo  | base64 -d > $R/sb_mask_phrase/PROMPT.md
cd $R/sb_mask_phrase && tmux new-session -d -s sb_mask_phrase "OMP_NUM_THREADS=8 MKL_NUM_THREADS=8 OPENBLAS_NUM_THREADS=8 nice -n 10 timeout 7200 agent -p -f --sandbox disabled --trust --model claude-opus-5-5-xhigh 'Read PROMPT.md in this folder and carry out the task it describes, completely.' > cursor.log 2>&1"
sleep 2; tmux ls -F "#{session_name}" | grep "^sb_" | tr "\n" " "; echo; tail -3 $R/sb_queue/codexq.log
for t in sb_mfrev sb_rlrev3; do echo "$t log=$(wc -c < $R/$t/cursor.log) v=$(ls $R/$t/REVIEW_VERDICT.md 2>/dev/null)"; done
for t in sb_f64rev2 sb_cntfix; do echo "== $t"; ls $R/$t/out | tr "\n" " "; echo; head -c 300 $R/$t/STATUS.md; echo; done
